/// Deine Spielwelt. Hier stellst du alles auf, was im Spiel vorkommt.
public class Welt extends Spielwelt {

   /// So viele Münzen hat der Spieler schon eingesammelt.
   private int punkte = 0;
   /// So viele Münzen liegen insgesamt in der Welt.
   private int anzahlMuenzen = 0;
   /// So viele Sekunden bleiben noch.
   private double zeit = 30;
   /// Solange das true ist, läuft das Spiel noch.
   private boolean laeuft = true;
   /// Die Anzeige oben links.
   private Text anzeige;
   /// Die Spielfigur. Sie ist eine Variable der Welt, damit run() sie anhalten kann.
   private Spieler held;

   public Welt() {
      this.baueRahmen();

      this.setzePflanze(0, 0, -120, 90);      // Baum
      this.setzePflanze(32, 0, 140, -40);     // Tanne
      this.setzePflanze(256, 128, 220, 110);  // Fels

      for (int x = -160; x <= 160; x = x + 80) {
         this.setzeMuenze(x, -130);
      }
      this.setzeMuenze(300, 140);

      anzeige = new Text("", 0, 200, 700);
      anzeige.setTextSize(20);
      anzeige.setTextColor(255, 255, 255);
      this.add(anzeige);

      held = new Spieler("boy");
      held.setPosition(-280, 0);
      this.add(held);
   }

   /// Umgibt die Wiese mit einem Rahmen aus Steinen.
   private void baueRahmen() {
      for (int x = -360; x <= 360; x = x + 48) {
         this.setzeStein(x, 192);
         this.setzeStein(x, -192);
      }
      for (int y = -144; y <= 144; y = y + 48) {
         this.setzeStein(-360, y);
         this.setzeStein(360, y);
      }
   }

   /// Setzt einen Stein, 16 × 16 Pixel groß, an die Stelle (pX, pY).
   private void setzeStein(double pX, double pY) {
      Hindernis stein = new Hindernis();
      stein.addCostume("stein", "assets/backgrounds/tilesets/tileset-dungeon.png", 128, 48, 16, 16);
      stein.setPosition(pX, pY);
      this.add(stein);
   }

   /// Setzt eine große Pflanze oder einen Felsen an die Stelle (pX, pY).
   /// pBildX und pBildY geben die linke obere Ecke im Kachelbild an, das Stück ist 32 × 32 Pixel groß.
   private void setzePflanze(int pBildX, int pBildY, double pX, double pY) {
      Hindernis pflanze = new Hindernis();
      pflanze.addCostume("pflanze", "assets/backgrounds/tilesets/tileset-nature.png", pBildX, pBildY, 32, 32);
      pflanze.setPosition(pX, pY);
      this.add(pflanze);
   }

   /// Legt eine Münze an die Stelle (pX, pY) und zählt sie mit.
   private void setzeMuenze(double pX, double pY) {
      Muenze m = new Muenze();
      m.setPosition(pX, pY);
      this.add(m);
      anzahlMuenzen = anzahlMuenzen + 1;
   }

   /// Liefert true, wenn alle Münzen eingesammelt sind.
   private boolean istGewonnen() {
      return punkte == anzahlMuenzen;
   }

   /// Hält das Spiel an und zeigt pMeldung an.
   private void beende(String pMeldung) {
      laeuft = false;
      held.setTempo(0);
      anzeige.showText(pMeldung);
   }

   /// Wird jedes Mal ausgeführt, wenn der Spieler eine Münze einsammelt.
   public void wennMuenzeEingesammelt() {
      punkte = punkte + 1;
   }

   /// Wird immer wieder ausgeführt, etwa 60-mal in der Sekunde.
   public void run() {
      if (laeuft) {
         zeit = zeit - 1.0 / 60;

         if (this.istGewonnen()) {
            this.beende("Gewonnen! Noch " + (int) zeit + " Sekunden übrig.");
         } else if (zeit <= 0) {
            this.beende("Die Zeit ist um! " + punkte + " von " + anzahlMuenzen + " Münzen.");
         } else {
            anzeige.showText("Münzen: " + punkte + " von " + anzahlMuenzen + "   Zeit: " + (int) zeit);
         }
      }
   }
}

/// Startet das Spiel.
void main() {
   // Pixelgrafik bleibt beim Vergrößern scharf.
   Window.useTextureSampling(TextureSampling.POINT);
   Window fenster = new Window(768, 432);
   fenster.setStage(new Welt());
}

/// Fertig für dich: eine Figur, durch die der Spieler nicht hindurchlaufen kann.
/// Ein Hindernis ist ein Sprite wie jedes andere. Sein Kostüm gibst du ihm selbst.
public class Hindernis extends Sprite {

   public Hindernis() {
      // Die Bilder sind winzig. Dreifach vergrößert passen sie zum Spieler.
      this.setSize(300);
   }

   /// Wie addCostume von Sprite. Zusätzlich hält nur die untere Hälfte des Bildes auf,
   /// also der Stamm eines Baums oder der Fuß eines Felsens. Hinter dem Rest kann man vorbeigehen.
   public void addCostume(String pName, String pBild, int pX, int pY, int pBreite, int pHoehe) {
      super.addCostume(pName, pBild, pX, pY, pBreite, pHoehe);
      this.setHitbox(0, pHoehe / 2.0, pBreite, pHoehe / 2.0, pBreite, pHoehe, 0, pHoehe);
   }
}

/// Fertig für dich: eine Münze, die sich dreht, bis der Spieler sie einsammelt.
public class Muenze extends AnimatedSprite {

   public Muenze() {
      // Vier Bilder zu je 10 × 10 Pixeln nebeneinander.
      this.addAnimation("drehen", "assets/items/treasure/coin2.png", 4, 10, 10);
      this.setAnimationInterval(150);
      this.setSize(300);
   }

   public void run() {
      this.playAnimation("drehen");
   }
}

/// Fertig für dich: die Figur, die du mit den Pfeiltasten steuerst.
/// Sie bleibt an Hindernissen hängen und sammelt Münzen ein.
/// Im Kapitel über Objektorientierung schaust du dir an, wie sie gebaut ist.
public class Spieler extends AnimatedSprite {

   /// So viele Pixel geht der Spieler in jedem Bild.
   private int tempo = 3;

   /// Erzeugt einen Spieler. pFigur ist ein Ordner in assets/actor/character/, zum Beispiel "boy".
   public Spieler(String pFigur) {
      String bild = "assets/actor/character/" + pFigur + "/sprite-sheet.png";
      // Im Bild steht jede Blickrichtung in einer eigenen Spalte,
      // die vier Schritte untereinander.
      this.addAnimation("unten", bild, 4, 16, 16, 0, true);
      this.addAnimation("oben", bild, 4, 16, 16, 1, true);
      this.addAnimation("links", bild, 4, 16, 16, 2, true);
      this.addAnimation("rechts", bild, 4, 16, 16, 3, true);
      this.setAnimationInterval(150);
      this.setSize(250);
      // Nur die Füße zählen: So kann die Figur vor einem Baum stehen, ohne an ihm hängen zu bleiben.
      this.setHitbox(4, 10, 12, 10, 12, 16, 4, 16);
      this.addSound("muenze", "assets/audio/sounds/bonus/coin.ogg");
   }

   public void run() {
      double altX = this.getX();
      double altY = this.getY();

      if (this.isKeyPressed(KeyCode.RIGHT)) {
         this.changeX(tempo);
         this.playAnimation("rechts");
      } else if (this.isKeyPressed(KeyCode.LEFT)) {
         this.changeX(-tempo);
         this.playAnimation("links");
      } else if (this.isKeyPressed(KeyCode.UP)) {
         this.changeY(tempo);
         this.playAnimation("oben");
      } else if (this.isKeyPressed(KeyCode.DOWN)) {
         this.changeY(-tempo);
         this.playAnimation("unten");
      }

      // In ein Hindernis hineingelaufen? Dann zurück auf den alten Platz.
      if (this.getTouchingSprite(Hindernis.class) != null) {
         this.setPosition(altX, altY);
      }

      Muenze m = this.getTouchingSprite(Muenze.class);
      if (m != null) {
         m.remove();
         this.playSound("muenze");
         Welt welt = (Welt) this.getStage();
         welt.wennMuenzeEingesammelt();
      }
   }

   /// Legt fest, wie viele Pixel der Spieler in jedem Bild geht. Mit 0 bleibt er stehen.
   public void setTempo(int pTempo) {
      tempo = pTempo;
   }
}

/// Fertig für dich: die Wiese als Hintergrund und die Reihenfolge, in der gezeichnet wird.
public class Spielwelt extends Stage {

   /// So viele Pixel ist eine Kachel auf der Bühne breit und hoch.
   public static final int KACHEL = 48;

   public Spielwelt() {
      // Die Wiese ist ein einziges Bild, so groß wie die Bühne.
      this.addBackdrop("wiese", "assets/backgrounds/wiese.png");

      // Wer weiter unten steht, ist näher am Betrachter: Er wird später gezeichnet
      // und verdeckt, was hinter ihm steht. So läuft man hinter Bäumen vorbei.
      this.getSorting().byY();
   }
}
